style.css:
@-moz-document domain("roblox.com") {
body {
        background-image: url("https://i.imgur.com/Q6cD66H.jpeg");
        background-size: cover;
        background-repeat: no-repeat;
        background-attachment: fixed;
        background-position: center;
    }

    /* Make white containers transparent */
    .container-main,
    .game-detail-page,
    .section,
    .rbx-body,
    .content,
    .navbar,
    .footer,
    .header,
    .container-header,
    .main-content {
        background: transparent !important;
        backdrop-filter: blur(4px); /* optional blur for readability */
    }

    /* Optional: remove Roblox grey background under everything */
    html {
        background: transparent !important;
    }
}
